// Simple side‑scrolling "Canvas Escape" game
// Canvas element with id="game" must exist in the HTML.

(() => {
  const canvas = document.getElementById('game');
  const ctx = canvas.getContext('2d');
  const W = canvas.width;
  const H = canvas.height;

  const PLAYER_SIZE = 20;
  const GROUND_HEIGHT = 30;
  const GRAVITY = 0.6;
  const JUMP_SPEED = -12;
  const OBSTACLE_WIDTH = 20;
  const GAP_WIDTH = 60;

  let speed = 2; // base scroll speed (px per frame)
  let frame = 0;
  let running = true;

  const player = {
    x: 50,
    y: H - GROUND_HEIGHT - PLAYER_SIZE,
    vy: 0,
    width: PLAYER_SIZE,
    height: PLAYER_SIZE,
  };

  const obstacles = [];

  function spawnObstacle() {
    // random spike or gap
    if (Math.random() < 0.5) {
      // spike: rectangle from ground up
      const height = 15 + Math.random() * 25;
      obstacles.push({
        type: 'spike',
        x: W,
        y: H - GROUND_HEIGHT - height,
        width: OBSTACLE_WIDTH,
        height,
      });
    } else {
      // gap: just a missing ground segment
      obstacles.push({
        type: 'gap',
        x: W,
        width: GAP_WIDTH,
      });
    }
  }

  function update() {
    if (!running) return;

    // player physics
    player.vy += GRAVITY;
    player.y += player.vy;
    // ground collision
    const groundY = H - GROUND_HEIGHT - PLAYER_SIZE;
    if (player.y > groundY) {
      player.y = groundY;
      player.vy = 0;
    }

    // obstacles movement
    for (let i = obstacles.length - 1; i >= 0; i--) {
      const o = obstacles[i];
      o.x -= speed;
      if (o.x + (o.width || 0) < 0) obstacles.splice(i, 1);
    }

    // spawn logic
    if (frame % Math.max(80 - speed * 10, 30) === 0) spawnObstacle();

    // collision detection
    for (const o of obstacles) {
      if (o.type === 'spike') {
        const hitX = player.x + player.width > o.x && player.x < o.x + o.width;
        const hitY = player.y + player.height > o.y;
        if (hitX && hitY) {
          running = false;
        }
      } else if (o.type === 'gap') {
        // if player is over the gap and on ground, they fall
        const overGap = player.x + player.width > o.x && player.x < o.x + o.width;
        const onGround = player.y + player.height >= H - GROUND_HEIGHT;
        if (overGap && onGround) {
          player.vy = JUMP_SPEED; // fall through gap
        }
      }
    }

    // speed ramp
    speed += 0.0005;
    frame++;
  }

  function draw() {
    ctx.clearRect(0, 0, W, H);

    // ground
    ctx.fillStyle = '#654321';
    ctx.fillRect(0, H - GROUND_HEIGHT, W, GROUND_HEIGHT);

    // obstacles
    ctx.fillStyle = '#ff0000';
    for (const o of obstacles) {
      if (o.type === 'spike') {
        ctx.fillRect(o.x, o.y, o.width, o.height);
      }
    }

    // player
    ctx.fillStyle = '#00ff00';
    ctx.fillRect(player.x, player.y, player.width, player.height);

    // simple game‑over overlay
    if (!running) {
      ctx.fillStyle = 'rgba(0,0,0,0.6)';
      ctx.fillRect(0, 0, W, H);
      ctx.fillStyle = '#fff';
      ctx.font = '24px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText('Game Over', W / 2, H / 2);
    }
  }

  function loop() {
    update();
    draw();
    if (running) requestAnimationFrame(loop);
  }

  // input – click or tap anywhere
  canvas.addEventListener('pointerdown', () => {
    if (!running) {
      // restart
      obstacles.length = 0;
      player.y = H - GROUND_HEIGHT - PLAYER_SIZE;
      player.vy = 0;
      speed = 2;
      frame = 0;
      running = true;
      requestAnimationFrame(loop);
    } else if (player.vy === 0) {
      player.vy = JUMP_SPEED;
    }
  });

  // start game
  requestAnimationFrame(loop);
})();
